import fs from "node:fs";

import { USERS, expect, sample, test, uniqueName } from "../../fixtures";

// features/audit.feature: Vendor audit trail
test("audit events are listed oldest first with actor and action", { tag: "@AUD-01" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const created = await member.post("/api/vendors", {
    data: { name: uniqueName("Audit Vendor"), category: "services", contact_email: "ops@audit-vendor.example" },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = await created.json();

  const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "w9",
      file: { name: "w9.txt", mimeType: "text/plain", buffer: fs.readFileSync(sample("w9.txt")) },
    },
  });
  expect(upload.status(), await upload.text()).toBe(201);

  // Act: extraction runs in the background, so poll until it has been recorded.
  let events: Array<{ action: string; actor: { id: string; name: string; email: string }; at: string }> = [];
  await expect
    .poll(
      async () => {
        const response = await member.get(`/api/vendors/${vendor.id}/audit`);
        expect(response.status(), await response.text()).toBe(200);
        events = (await response.json()).items;
        return events.map((e) => e.action);
      },
      { timeout: 15_000 },
    )
    .toEqual(["vendor.created", "document.uploaded", "document.extracted"]);

  // Assert: each event names the actor and a timestamp
  for (const event of events) {
    expect(event.actor.email, `actor of ${event.action}`).toBe(USERS.member);
    expect(event.actor.name, `actor name of ${event.action}`).toBeTruthy();
    expect(Number.isNaN(Date.parse(event.at)), `timestamp of ${event.action}: ${event.at}`).toBe(false);
  }
});
